window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d4d4704cb1eb3f37"]={"versions": [{"id": "FIG-d4d4704cb1eb3f37", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Software-Architekturdiagramm (AUTOSAR Classic Platform, Component and Composition Modeling). Das Diagramm illustriert eine unzulässige 1:n- bzw. n:1-Sender-Receiver-Verbindungskonfiguration zwischen zwei Software-Komponenten vom Typ <code>ApplicationSwComponentType</code> und einer <code>NvBlockSwComponentType</code> auf Kompositionsebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert drei Komponenten:</p>\n<ul class=\"fig-list\"><li>Komponente A (<code>ApplicationSwComponentType</code>): Enthält eine <code>RunnableEntity</code> mit Lesezugriff (<code>Read Access</code>) auf einen R-Port (Empfänger-Port).\n</li><li>Komponente B (<code>NvBlockSwComponentType</code>): Enthält einen <code>ramBlock</code>, ein internes <code>Mapping</code> auf diesen RAM-Block sowie einen P-Port (Sender-Port).\n</li><li>Komponente C (<code>ApplicationSwComponentType</code>): Enthält eine <code>RunnableEntity</code> mit Schreibzugriff (<code>Write Access</code>) auf einen P-Port (Sender-Port).\n</li><li>Assembly-Konnektoren (<code>Connector</code>): Verbindungsleitungen zwischen den P-Ports von B und C hin zum gemeinsamen R-Port von A. Ein Smiley-Symbol mit unglücklicher Mimik visualisiert die Ungültigkeit dieses Entwurfs.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Datenflüsse verlaufen theoretisch von Komponente C (<code>RunnableEntity</code> -&gt; <code>Write Access</code> -&gt; P-Port) und von Komponente B (<code>ramBlock</code> -&gt; <code>Mapping</code> -&gt; P-Port) über Konnektoren zum selben R-Port von Komponente A (<code>Read Access</code> -&gt; <code>RunnableEntity</code>). Das Zusammenführen zweier Sender-Ports (eines normalen Application-P-Ports und eines NvBlock-P-Ports) auf denselben R-Port ist semantisch ungültig, da ein Empfänger nicht gleichzeitig und unkoordiniert über einen Standard-Connector von zwei verschiedenen Providern versorgt werden kann.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert ein architektonisches Negativbeispiel (invalid connection). Die Modellierungsregel untersagt das gleichzeitige Verschalten eines NvBlockSwComponentType-Provider-Ports und eines ApplicationSwComponentType-Provider-Ports auf einen gemeinsamen Receiver-Port eines ApplicationSwComponentType. Entwickler müssen sicherstellen, dass Sender-Receiver-Verbindungen entweder strikt 1:1 oder mit eindeutig spezifizierten 1:n- bzw. n:1-Semantiken modelliert werden, wobei NvBlock-Interaktionen dedizierte Schnittstellenkonventionen erfordern.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a482c5a96784c7cd", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Software-Architekturdiagramm (AUTOSAR Classic Platform, Component and Composition Modeling). Das Diagramm illustriert eine unzulässige 1:n- bzw. n:1-Sender-Receiver-Verbindungskonfiguration zwischen zwei Software-Komponenten vom Typ <code>ApplicationSwComponentType</code> und einer <code>NvBlockSwComponentType</code> auf Kompositionsebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert drei Komponenten:</p>\n<ul class=\"fig-list\"><li>Komponente A (<code>ApplicationSwComponentType</code>): Enthält eine <code>RunnableEntity</code> mit Lesezugriff (<code>Read Access</code>) auf einen R-Port (Empfänger-Port).\n</li><li>Komponente B (<code>NvBlockSwComponentType</code>): Enthält einen <code>ramBlock</code>, ein internes <code>Mapping</code> auf diesen RAM-Block sowie einen P-Port (Sender-Port).\n</li><li>Komponente C (<code>ApplicationSwComponentType</code>): Enthält eine <code>RunnableEntity</code> mit Schreibzugriff (<code>Write Access</code>) auf einen P-Port (Sender-Port).\n</li><li>Assembly-Konnektoren (<code>Connector</code>): Verbindungsleitungen zwischen den P-Ports von B und C hin zum gemeinsamen R-Port von A. Ein Smiley-Symbol mit unglücklicher Mimik visualisiert die Ungültigkeit dieses Entwurfs.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Datenflüsse verlaufen theoretisch von Komponente C (<code>RunnableEntity</code> -&gt; <code>Write Access</code> -&gt; P-Port) und von Komponente B (<code>ramBlock</code> -&gt; <code>Mapping</code> -&gt; P-Port) über Konnektoren zum selben R-Port von Komponente A (<code>Read Access</code> -&gt; <code>RunnableEntity</code>). Das Zusammenführen zweier Sender-Ports (eines normalen Application-P-Ports und eines NvBlock-P-Ports) auf denselben R-Port ist semantisch ungültig, da ein Empfänger nicht gleichzeitig und unkoordiniert über einen Standard-Connector von zwei verschiedenen Providern versorgt werden kann.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert ein architektonisches Negativbeispiel (invalid connection). Die Modellierungsregel untersagt das gleichzeitige Verschalten eines NvBlockSwComponentType-Provider-Ports und eines ApplicationSwComponentType-Provider-Ports auf einen gemeinsamen Receiver-Port eines ApplicationSwComponentType. Entwickler müssen sicherstellen, dass Sender-Receiver-Verbindungen entweder strikt 1:1 oder mit eindeutig spezifizierten 1:n- bzw. n:1-Semantiken modelliert werden, wobei NvBlock-Interaktionen dedizierte Schnittstellenkonventionen erfordern.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f7bd3ce1164cd42b", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Software-Architekturdiagramm (AUTOSAR Classic Platform, Component and Composition Modeling). Das Diagramm illustriert eine unzulässige 1:n- bzw. n:1-Sender-Receiver-Verbindungskonfiguration zwischen zwei Software-Komponenten vom Typ <code>ApplicationSwComponentType</code> und einer <code>NvBlockSwComponentType</code> auf Kompositionsebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert drei Komponenten:</p>\n<ul class=\"fig-list\"><li>Komponente A (<code>ApplicationSwComponentType</code>): Enthält eine <code>RunnableEntity</code> mit Lesezugriff (<code>Read Access</code>) auf einen R-Port (Empfänger-Port).\n</li><li>Komponente B (<code>NvBlockSwComponentType</code>): Enthält einen <code>ramBlock</code>, ein internes <code>Mapping</code> auf diesen RAM-Block sowie einen P-Port (Sender-Port).\n</li><li>Komponente C (<code>ApplicationSwComponentType</code>): Enthält eine <code>RunnableEntity</code> mit Schreibzugriff (<code>Write Access</code>) auf einen P-Port (Sender-Port).\n</li><li>Assembly-Konnektoren (<code>Connector</code>): Verbindungsleitungen zwischen den P-Ports von B und C hin zum gemeinsamen R-Port von A. Ein Smiley-Symbol mit unglücklicher Mimik visualisiert die Ungültigkeit dieses Entwurfs.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Datenflüsse verlaufen theoretisch von Komponente C (<code>RunnableEntity</code> -&gt; <code>Write Access</code> -&gt; P-Port) und von Komponente B (<code>ramBlock</code> -&gt; <code>Mapping</code> -&gt; P-Port) über Konnektoren zum selben R-Port von Komponente A (<code>Read Access</code> -&gt; <code>RunnableEntity</code>). Das Zusammenführen zweier Sender-Ports (eines normalen Application-P-Ports und eines NvBlock-P-Ports) auf denselben R-Port ist semantisch ungültig, da ein Empfänger nicht gleichzeitig und unkoordiniert über einen Standard-Connector von zwei verschiedenen Providern versorgt werden kann.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert ein architektonisches Negativbeispiel (invalid connection). Die Modellierungsregel untersagt das gleichzeitige Verschalten eines NvBlockSwComponentType-Provider-Ports und eines ApplicationSwComponentType-Provider-Ports auf einen gemeinsamen Receiver-Port eines ApplicationSwComponentType. Entwickler müssen sicherstellen, dass Sender-Receiver-Verbindungen entweder strikt 1:1 oder mit eindeutig spezifizierten 1:n- bzw. n:1-Semantiken modelliert werden, wobei NvBlock-Interaktionen dedizierte Schnittstellenkonventionen erfordern.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d58d6e4edcb3111a", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Software-Architekturdiagramm (AUTOSAR Classic Platform, Component and Composition Modeling). Das Diagramm illustriert eine unzulässige 1:n- bzw. n:1-Sender-Receiver-Verbindungskonfiguration zwischen zwei Software-Komponenten vom Typ <code>ApplicationSwComponentType</code> und einer <code>NvBlockSwComponentType</code> auf Kompositionsebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert drei Komponenten:</p>\n<ul class=\"fig-list\"><li>Komponente A (<code>ApplicationSwComponentType</code>): Enthält eine <code>RunnableEntity</code> mit Lesezugriff (<code>Read Access</code>) auf einen R-Port (Empfänger-Port).\n</li><li>Komponente B (<code>NvBlockSwComponentType</code>): Enthält einen <code>ramBlock</code>, ein internes <code>Mapping</code> auf diesen RAM-Block sowie einen P-Port (Sender-Port).\n</li><li>Komponente C (<code>ApplicationSwComponentType</code>): Enthält eine <code>RunnableEntity</code> mit Schreibzugriff (<code>Write Access</code>) auf einen P-Port (Sender-Port).\n</li><li>Assembly-Konnektoren (<code>Connector</code>): Verbindungsleitungen zwischen den P-Ports von B und C hin zum gemeinsamen R-Port von A. Ein Smiley-Symbol mit unglücklicher Mimik visualisiert die Ungültigkeit dieses Entwurfs.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Datenflüsse verlaufen theoretisch von Komponente C (<code>RunnableEntity</code> -&gt; <code>Write Access</code> -&gt; P-Port) und von Komponente B (<code>ramBlock</code> -&gt; <code>Mapping</code> -&gt; P-Port) über Konnektoren zum selben R-Port von Komponente A (<code>Read Access</code> -&gt; <code>RunnableEntity</code>). Das Zusammenführen zweier Sender-Ports (eines normalen Application-P-Ports und eines NvBlock-P-Ports) auf denselben R-Port ist semantisch ungültig, da ein Empfänger nicht gleichzeitig und unkoordiniert über einen Standard-Connector von zwei verschiedenen Providern versorgt werden kann.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert ein architektonisches Negativbeispiel (invalid connection). Die Modellierungsregel untersagt das gleichzeitige Verschalten eines NvBlockSwComponentType-Provider-Ports und eines ApplicationSwComponentType-Provider-Ports auf einen gemeinsamen Receiver-Port eines ApplicationSwComponentType. Entwickler müssen sicherstellen, dass Sender-Receiver-Verbindungen entweder strikt 1:1 oder mit eindeutig spezifizierten 1:n- bzw. n:1-Semantiken modelliert werden, wobei NvBlock-Interaktionen dedizierte Schnittstellenkonventionen erfordern.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-d4d4704cb1eb3f37", "to": "FIG-a482c5a96784c7cd", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a482c5a96784c7cd", "to": "FIG-f7bd3ce1164cd42b", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f7bd3ce1164cd42b", "to": "FIG-d58d6e4edcb3111a", "fr": "R20-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Weißer Randbeschnitt: Weißraum oben und unten stark reduziert (Seitenverhältnis von ca. 4:3 auf ca. 16:9 geändert).\n</li><li>Schrifttypografie: Ersetzung der Serifenschrift (Times-Variante) durch eine serifenlose Schriftart (Helvetica/Arial-Stil) bei allen Modellelement- und Portbeschriftungen.\n</li></ul>"}]};
